def solve(s):
    # Check if the string contains any letters (alphabetic characters)
    has_letter = any(c.isalpha() for c in s)

    result_chars = []

    if not has_letter:
        # If no letters, reverse the entire string
        return s[::-1]
    else:
        # If there are letters, process each character:
        # - Reverse case for letters
        # - Keep non-letters unchanged
        for c in s:
            if c.isalpha():
                result_chars.append(c.swapcase())
            else:
                result_chars.append(c)

        return ''.join(result_chars)


